 "content": "def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    color_counts = Counter(v for row in grid for v in row)
    bg = color_counts.most_common(1)[0][0]

    # A rail is a uniform full row/column in a non-background color. If more
    # than one exists, the less frequent full-line color is the rail.
    rails = []
    for r in range(h):
        if len(set(grid[r])) == 1 and grid[r][0] != bg:
            rails.append(('row', r, grid[r][0]))
    for c in range(w):
        col = [grid[r][c] for r in range(h)]
        if len(set(col)) == 1 and col[0] != bg:
            rails.append(('col', c, col[0]))
    if not rails:
        return [row[:] for row in grid]
    axis, pos, rail_color = min(rails, key=lambda rail: color_counts[rail[2]])

    cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
             if grid[r][c] != bg and grid[r][c] != rail_color]
    if not cells:
        return [row[:] for row in grid]
    out = [row[:] for row in grid]

    if axis == 'row':
        lo, hi = min(r for r, c, v in cells), max(r for r, c, v in cells)
        direction = -1 if lo > pos else 1
        occupied = {(r, c) for r, c, v in cells}
        moved = [(r + direction, c, v) for r, c, v in cells]
        can_move = all(0 <= r < h and
                       (grid[r][c] == bg or (r, c) in occupied)
                       for r, c, v in moved)
        if can_move:
            for r, c, v in cells:
                out[r][c] = bg
            for r, c, v in moved:
                out[r][c] = v
            stripe = hi if direction < 0 else lo
        else:
            stripe = lo - 1 if direction < 0 else hi + 1
        if 0 <= stripe < h:
            out[stripe] = [8] * w
    else:
        lo, hi = min(c for r, c, v in cells), max(c for r, c, v in cells)
        direction = -1 if lo > pos else 1
        occupied = {(r, c) for r, c, v in cells}
        moved = [(r, c + direction, v) for r, c, v in cells]
        can_move = all(0 <= c < w and
                       (grid[r][c] == bg or (r, c) in occupied)
                       for r, c, v in moved)
        if can_move:
            for r, c, v in cells:
                out[r][c] = bg
            for r, c, v in moved:
                out[r][c] = v
            stripe = hi if direction < 0 else lo
        else:
            stripe = lo - 1 if direction < 0 else hi + 1
        if 0 <= stripe < w:
            for r in range(h):
                out[r][stripe] = 8
    return out

if __name__ == '__main__':
    pass
