    freq = Counter(v for row in grid for v in row)
    # In these tasks background is the abundant color, rail is a distinct
    # uniformly colored full row/column (or overpainted by object once).
    bg = freq.most_common(1)[0][0]
    if len(freq) >= 2:
        rail_color = min(freq, key=freq.get)
    else:
        return [row[:] for row in grid]

    rail = None
    # Strong evidence: full row/column of rail color, allowing object overlay.
    for r, row in enumerate(grid):
        if sum(v == rail_color for v in row) >= w - 1:
            rail = ('row', r, rail_color)
            break
    if rail is None:
        for c in range(w):
            if sum(grid[r][c] == rail_color for r in range(h)) >= h - 1:
                rail = ('col', c, rail_color)
                break
    if rail is None:
        return [row[:] for row in grid]

    axis, p, rail_color = rail
    cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
             if grid[r][c] != bg and grid[r][c] != rail_color]
    if not cells:
        return [row[:] for row in grid]
    out = [row[:] for row in grid]

    if axis == 'row':
        lo, hi = min(r for r,c,v in cells), max(r for r,c,v in cells)
        d = -1 if lo > p else 1
