    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # A complete straight line in the contrasting color is the rail.
    rail = None
    for r in range(h):
        if len(set(grid[r])) == 1 and grid[r][0] != bg:
            rail = ('row', r, grid[r][0]); break
    if rail is None:
        for c in range(w):
            col = [grid[r][c] for r in range(h)]
            if len(set(col)) == 1 and col[0] != bg:
                rail = ('col', c, col[0]); break
    if rail is None:
        # Demo 1's rail is partially hidden beneath the wide block.
        for r in range(h):
            row = grid[r]
            for color in set(row):
                if color == bg: continue
                ix = [c for c, v in enumerate(row) if v == color]
                if len(ix) >= w - 2 and max(ix) - min(ix) + 1 == len(ix):
                    rail = ('row', r, color); break
            if rail: break
    if rail is None:
        return [row[:] for row in grid]

    axis, p, rail_color = rail
    obj = [(r,c,grid[r][c]) for r in range(h) for c in range(w)
           if grid[r][c] != bg and grid[r][c] != rail_color]
    out = [row[:] for row in grid]
    if axis == 'row':
        lo, hi = min(r for r,c,v in obj), max(r for r,c,v in obj)
        # Move one cell toward rail, allowing cells occupied by the same object.
        d = -1 if lo > p else 1
        occupied = {(r,c) for r,c,v in obj}
        moved = [(r+d,c,v) for r,c,v in obj]
        can_move = all(0 <= r < h and (grid[r][c] == bg or (r,c) in occupied) for r,c,v in moved)
        if can_move:
            for r,c,v in obj: out[r][c] = bg
            for r,c,v in moved: out[r][c] = v
            stripe = hi if d < 0 else lo
        else:
            stripe = lo - 1 if d < 0 else hi + 1
        if 0 <= stripe < h: out[stripe] = [8]*w
    else:
        lo, hi = min(c for r,c,v in obj), max(c for r,c,v in obj)
        d = -1 if lo > p else 1
        occupied = {(r,c) for r,c,v in obj}
        moved = [(r,c+d,v) for r,c,v in obj]
