 "content": "def transform(grid):
    """Move the foreground pattern toward its line and mark the old edge."""
    from collections import Counter

    h, w = len(grid), len(grid[0])
    border = grid[0] + grid[-1] + [grid[r][0] for r in range(h)] + [grid[r][-1] for r in range(h)]
    bg = Counter(border).most_common(1)[0][0]

    # Find the full uniform rail (some training cases have it occluded).
    rail = None
    for r, row in enumerate(grid):
        if len(set(row)) == 1 and row[0] != bg:
            rail = ("row", r, row[0]); break
    if rail is None:
        for c in range(w):
            col = [grid[r][c] for r in range(h)]
            if len(set(col)) == 1 and col[0] != bg:
                rail = ("col", c, col[0]); break
    if rail is None:
        # Recover vertical rail in demo 1.
        for c in range(w):
            vals = [grid[r][c] for r in range(h) if grid[r][c] != bg]
            if len(vals) == h and vals and len(set(vals)) == 1:
                rail = ("col", c, vals[0]); break
    if rail is None:
        # Recover horizontal rail in demo 2.
        for r, row in enumerate(grid):
            for color in set(row):
                if color == bg: continue
                inds = [c for c, v in enumerate(row) if v == color]
                if len(inds) >= w - 2 and max(inds) - min(inds) + 1 == len(inds):
                    rail = ("row", r, color); break
            if rail: break
    if rail is None:
        return [row[:] for row in grid]

    axis, rail_pos, rail_color = rail
    motif = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
             if grid[r][c] != bg and grid[r][c] != rail_color]
    if not motif:
        return [row[:] for row in grid]

    out = [row[:] for row in grid]
    if axis == "col":
        left, right = min(c for _, c, _ in motif), max(c for _, c, _ in motif)
        if right < rail_pos:
            gap = rail_pos - right - 1
            moved = [(r, c + gap, v) for r, c, v in motif]
            stripe = left + gap - 1
        else:
            gap = left - rail_pos - 1
            moved = [(r, c - gap, v) for r, c, v in motif]
            stripe = right - gap + 1
        for r, c, _ in motif: out[r][c] = bg
        for r, c, v in moved: out[r][c] = v
        if 0 <= stripe < w:
            for r in range(h): out[r][stripe] = 8
    else:
        top, bottom = min(r for r, _, _ in motif), max(r for r, _, _ in motif)
        if bottom < rail_pos:
            gap = rail_pos - bottom - 1
            moved = [(r + gap, c, v) for r, c, v in motif]
            stripe = top + gap - 1
        else:
            gap = top - rail_pos - 1
            moved = [(r - gap, c, v) for r, c, v in motif]
            stripe = bottom - gap + 1
        old = {(r, c) for r, c, _ in motif}
        for r, c, _ in motif: out[r][c] = bg
        for r, c, v in moved: out[r][c] = v
        if 0 <= stripe < h:
            for c in range(w):
                out[stripe][c] = bg if gap > 1 and (stripe, c) in old else 8
    return out

